import{_ as i,a0 as l,w as n,s,I as p,x as r,a1 as a,A as d,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"一些不起眼但非常有用的 Vim 命令 | LCTT x X-CMD","titleTemplate":false,"description":"一些不起眼但非常有用的 Vim 命令 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些不起眼但非常有用的 Vim 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些不起眼但非常有用的 Vim 命令 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141115 What are some obscure but useful Vim commands","title":"一些不起眼但非常有用的 Vim 命令","tag":"201501","desc":""},"relativePath":"201501/20141115 What are some obscure but useful Vim commands.md","filePath":"[post].md"}'),m={name:"201501/20141115 What are some obscure but useful Vim commands.md"};function c(f,e,h,u,b,V){const o=l("Link");return n(),s("div",null,[e[22]||(e[22]=p("h1",{id:"一些不起眼但非常有用的-vim-命令",tabindex:"-1"},[r("一些不起眼但非常有用的 Vim 命令 "),p("a",{class:"header-anchor",href:"#一些不起眼但非常有用的-vim-命令","aria-label":"Permalink to “一些不起眼但非常有用的 Vim 命令”"},"​")],-1)),p("p",null,[e[1]||(e[1]=r("如果我的",-1)),a(o,{href:"http://xmodulo.com/turn-vim-full-fledged-ide.html"},{default:d(()=>[...e[0]||(e[0]=[r("关于这个话题的最新帖子",-1)])]),_:1}),e[2]||(e[2]=r("没有提醒到你的话，那我明确地说，我是一个 Vim 的粉丝。所以在你们中的某些人向我扔石头之前，我先向你们展示一系列“鲜为人知的 Vim 命令”。我的意思是，一些你可能以前没有碰到过的命令，但可能对你来说很有用。作为第二免责声明，我不知道哪些命令是你可能知道的，以及哪些是对你来说有用的。因此这些命令实际上是一些相对少见，但很可能很有用的 Vim 命令。",-1))]),e[23]||(e[23]=t(`<h3 id="保存文件并退出" tabindex="-1">保存文件并退出 <a class="header-anchor" href="#保存文件并退出" aria-label="Permalink to “保存文件并退出”">​</a></h3><p>说起来有些惭愧，我也是最近才学到这个命令</p><pre><code>:x
</code></pre><p>和下面的命令是等价的：</p><pre><code>:wq
</code></pre><p>都是保存当前文件并退出。</p><p>（译者注：这两个命令实际上并不完全等价，当文件被修改时两个命令时相同的。但如果未被修改，使用 <code>:x</code> 不会更改文件的修改时间，而使用 <code>:wq</code> 会改变文件的修改时间。）</p><h3 id="基本计算器" tabindex="-1">基本计算器 <a class="header-anchor" href="#基本计算器" aria-label="Permalink to “基本计算器”">​</a></h3><p>在插入模式下，你可以使用 Ctrl+r 键然后输入 <code>=</code>，再输入一个简单的算式。按 Enter 键，计算结果就会插入到文件中。例如，尝试输入：</p><pre><code>Ctrl+r &#39;=2+2&#39; ENTER
</code></pre><p><img src="https://farm8.staticflickr.com/7486/15543918097_fbcf33ee6b.jpg" alt=""></p><p>然后计算结果“4 ”会被插入到文件中。</p><h3 id="查找重复的连续的单词" tabindex="-1">查找重复的连续的单词 <a class="header-anchor" href="#查找重复的连续的单词" aria-label="Permalink to “查找重复的连续的单词”">​</a></h3><p>当你很快地打字时，很有可能会连续输入同一个单词两次，就像 this this。这种错误可能骗过任何一个人，即使是你自己重新阅读一遍也不可避免。幸运的是，有一个简单的正则表达式可以用来预防这个错误。使用搜索命令（默认时 <code>/</code>）然后输入：</p><pre><code>\\(\\&lt;\\w\\+\\&gt;\\)\\_s*\\1
</code></pre><p>这会显示所有重复的单词。要达到最好的效果，不要忘记把下面的命令：</p><pre><code>set hlsearch
</code></pre><p>放到你的 .vimrc 文件中高亮所有的匹配。</p><p><img src="https://farm8.staticflickr.com/7531/15730650082_c2764857e2.jpg" alt=""></p><h3 id="缩写" tabindex="-1">缩写 <a class="header-anchor" href="#缩写" aria-label="Permalink to “缩写”">​</a></h3><p>一个很可能是最令人印象深刻的窍门是你可以在 Vim 中定义缩写，它可以实时地把你输入的东西替换为另外的东西。语法格式如下：</p><pre><code>:ab [缩写] [要替换的文字]
</code></pre><p>一个通用的例子是：</p><pre><code>:ab asap as soon as possible
</code></pre><p>会把你输入的 “asap” 替换为 “as soon as possible”。</p><h3 id="在你忘记用-root-方式打开文件时的文件保存" tabindex="-1">在你忘记用 root 方式打开文件时的文件保存 <a class="header-anchor" href="#在你忘记用-root-方式打开文件时的文件保存" aria-label="Permalink to “在你忘记用 root 方式打开文件时的文件保存”">​</a></h3><p>这可能是一个在论坛中一直受欢迎的命令。每当你打开一个你没有写入权限的文件（比如系统配置文件）并做了一些修改，Vim 无法通过普通的 “:w” 命令来保存。</p><p>你不需要重新以 root 方式打开文件再进行修改，只需要运行：</p><pre><code>:w !sudo tee %
</code></pre><p>这会直接以 root 方式保存。</p><h3 id="实时加密文本" tabindex="-1">实时加密文本 <a class="header-anchor" href="#实时加密文本" aria-label="Permalink to “实时加密文本”">​</a></h3>`,31)),p("p",null,[e[4]||(e[4]=r("如果你不想让别人看懂你的屏幕上的内容，你可以使用一个内置的选项，通过下面的命令使用 ",-1)),a(o,{href:"https://en.wikipedia.org/wiki/ROT13"},{default:d(()=>[...e[3]||(e[3]=[r("ROT13",-1)])]),_:1}),e[5]||(e[5]=r(" 来对文本进行编码：",-1))]),e[24]||(e[24]=t(`<pre><code>ggVGg?
</code></pre><p><img src="https://farm8.staticflickr.com/7487/15727174681_7773a97ea2.jpg" alt=""></p><p><code>gg</code> 把光标移动到 Vim 缓冲区的第一行，<code>V</code> 进入可视模式，<code>G</code> 把光标移动到缓冲区的最后一行。因此，<code>ggVG</code> 使可视模式覆盖这个当前缓冲区。最后 <code>g?</code> 使用 ROT13 对整个区域进行编码。</p><p>注意它可以被映射到一个最常使用的键。它对字母符号也可以很好地工作。要对它进行撤销，最好的方法就是使用撤销命令：<code>u</code>。</p><p>###自动补全 ###</p><p>这是另外一个令我感到惭愧的功能，但我发现周围很多人并不知道。Vim 默认有自动补全的功能。的确这个功能是很基本的，并且可以通过插件来增强，但它也很有帮助。方法很简单。Vim 尝试通过已经输入的单词来预测单词的结尾。比如当你在同一个文件中第二次输入 “compiler” 时，仅仅输入 “com” 然后保持在插入模式，按 Ctrl+n 键就可以看到 Vim 为你补全了单词。很简单，但也很有用。</p><h3 id="比较两个文件的不同" tabindex="-1">比较两个文件的不同 <a class="header-anchor" href="#比较两个文件的不同" aria-label="Permalink to “比较两个文件的不同”">​</a></h3><p>你们中的大多数很可能都知道 vimdiff 命令，它可以使用分离模式打开 Vim 并比较两个文件的不同。语法如下：</p><pre><code>$ vimdiff [文件1] [文件2]
</code></pre><p>但同样的结果也可以通过下面的 Vim 命令来获得：</p><pre><code>:diffthis
</code></pre><p>首先在 Vim 中打开原始文件。然后使用分离模式带来第二个文件：</p><pre><code>:vsp [文件2]
</code></pre><p>最后在第一个缓冲区里输入：</p><pre><code>:diffthis
</code></pre><p>通过 Ctrl+w 来切换缓冲区并再次输入：</p><pre><code>:diffthis
</code></pre><p>这样两个文件中不同的部分就会被高亮。</p><p>（译者注：可以直接在一个缓冲区里使用命令 <code>:windo diffthis</code>，而不用输入 <code>:diffthis</code> 两次）</p><p>要停止比较，使用：</p><pre><code>:diffoff
</code></pre><h3 id="按时间回退文件" tabindex="-1">按时间回退文件 <a class="header-anchor" href="#按时间回退文件" aria-label="Permalink to “按时间回退文件”">​</a></h3><p>Vim 会记录文件的更改，你很容易可以回退到之前某个时间。该命令是相当直观的。比如：</p><pre><code>:earlier 1m
</code></pre><p>会把文件回退到 1 分钟以前的状态。</p><p>注意，你可以使用下面的命令进行相反的转换：</p><pre><code>:later
</code></pre><h3 id="删除标记内部的文字" tabindex="-1">删除标记内部的文字 <a class="header-anchor" href="#删除标记内部的文字" aria-label="Permalink to “删除标记内部的文字”">​</a></h3><p>当我开始使用 Vim 时，一件我总是想很方便做的事情是如何轻松的删除方括号或圆括号里的内容。转到开始的标记，然后使用下面的语法：</p><pre><code>di[标记]
</code></pre><p>比如，把光标放在开始的圆括号上，使用下面的命令来删除圆括号内的文字：</p><pre><code>di(
</code></pre><p>如果是方括号或者是引号，则使用：</p><pre><code>di{
</code></pre><p>和：</p><pre><code>di&quot;
</code></pre><h3 id="删除指定标记前的内容" tabindex="-1">删除指定标记前的内容 <a class="header-anchor" href="#删除指定标记前的内容" aria-label="Permalink to “删除指定标记前的内容”">​</a></h3><p>和删除标记内部有些相似，但目的不同。命令如下：</p><pre><code>dt[标记]
</code></pre><p>会删除所有光标和标记之间的内容（保持标记不动），如果在同一行有这个标记的话。例如</p><pre><code>dt.
</code></pre><p>会删除至句子的末尾，但保持 ‘.’ 不动。</p><h3 id="把-vim-变为十六进制编辑器" tabindex="-1">把 Vim 变为十六进制编辑器 <a class="header-anchor" href="#把-vim-变为十六进制编辑器" aria-label="Permalink to “把 Vim 变为十六进制编辑器”">​</a></h3><p>这不是我最喜欢的窍门，但有时会很有趣。你可以把 Vim 和 xxd 功能连起来来把文件转换为十六进制模式。命令如下：</p><pre><code>:%!xxd
</code></pre><p><img src="https://farm6.staticflickr.com/5607/15109142674_e99466f2db_z.jpg" alt=""></p><p>类似的，你可以通过下面的命令恢复原来的状态：</p><pre><code>:%!xxd -r
</code></pre><h3 id="把光标下的文字置于屏幕中央" tabindex="-1">把光标下的文字置于屏幕中央 <a class="header-anchor" href="#把光标下的文字置于屏幕中央" aria-label="Permalink to “把光标下的文字置于屏幕中央”">​</a></h3><p>我们所要做的事情如标题所示。如果你想强制滚动屏幕来把光标下的文字置于屏幕的中央，在可视模式中使用命令（译者注：在普通模式中也可以）：</p><pre><code>zz
</code></pre><h3 id="跳到上一个-下一个位置" tabindex="-1">跳到上一个／下一个位置 <a class="header-anchor" href="#跳到上一个-下一个位置" aria-label="Permalink to “跳到上一个／下一个位置”">​</a></h3><p>当你编辑一个很大的文件时，经常要做的事是在某处进行修改，然后跳到另外一处。如果你想跳回之前修改的地方，使用命令：</p><pre><code>Ctrl+o
</code></pre><p>来回到之前修改的地方</p><p>类似的：</p><pre><code>Ctrl+i
</code></pre><p>会回退上面的跳动。</p><h3 id="把当前文件转化为网页" tabindex="-1">把当前文件转化为网页 <a class="header-anchor" href="#把当前文件转化为网页" aria-label="Permalink to “把当前文件转化为网页”">​</a></h3><p>这会生成一个 HTML 文件来显示文本，并在分开的窗口显示源代码：</p><pre><code>:%TOhtml
</code></pre><p>（译者注：原文是 <code>:%Tohtml</code>，但在我的电脑上是 <code>:%TOhtml</code>）</p><p><img src="https://farm8.staticflickr.com/7550/15727174701_c405f85a84_z.jpg" alt=""></p><p>很基本但很不错。</p>`,64)),p("p",null,[e[7]||(e[7]=r("总的来说，这一系列命令是在我读了许多论坛主题和 ",-1)),a(o,{href:"http://vim.wikia.com/wiki/Vim_Tips_Wiki"},{default:d(()=>[...e[6]||(e[6]=[r("Vim Tips wiki",-1)])]),_:1}),e[8]||(e[8]=r("（如果你想学习更多关于编辑器的知识，我非常推荐这篇文章） 之后收集起来的。",-1))]),e[25]||(e[25]=p("p",null,"如果你还知道哪些非常有用但你认为大多数人并不知道的命令，可以随意在评论中分享出来。就像引言中所说的，一个“鲜为人知但很有用的”命令也许只是你自己的看法，但分享出来总是好的。",-1)),e[26]||(e[26]=p("hr",null,null,-1)),p("p",null,[e[10]||(e[10]=r("via: ",-1)),a(o,{href:"http://xmodulo.com/useful-vim-commands.html"},{default:d(()=>[...e[9]||(e[9]=[r("http://xmodulo.com/useful-vim-commands.html",-1)])]),_:1})]),p("p",null,[e[14]||(e[14]=r("作者：",-1)),a(o,{href:"http://xmodulo.com/author/adrien"},{default:d(()=>[...e[11]||(e[11]=[r("Adrien Brochard",-1)])]),_:1}),e[15]||(e[15]=r(" 译者：",-1)),a(o,{href:"https://github.com/wangjiezhe"},{default:d(()=>[...e[12]||(e[12]=[r("wangjiezhe",-1)])]),_:1}),e[16]||(e[16]=r(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:d(()=>[...e[13]||(e[13]=[r("wxy",-1)])]),_:1})]),p("p",null,[e[19]||(e[19]=r("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[17]||(e[17]=[r("LCTT",-1)])]),_:1}),e[20]||(e[20]=r(" 原创翻译，",-1)),a(o,{href:"http://linux.cn/"},{default:d(()=>[...e[18]||(e[18]=[r("Linux中国",-1)])]),_:1}),e[21]||(e[21]=r(" 荣誉推出",-1))])])}const k=i(m,[["render",c]]);export{g as __pageData,k as default};
